alter table public.app_settings enable row level security; drop policy if exists "Authenticated users can read app settings" on public.app_settings; create policy "Authenticated users can read app settings" on public.app_settings for select to authenticated using (true); drop policy if exists "Super admins can manage app settings" on public.app_settings; create policy "Super admins can manage app settings" on public.app_settings for all to authenticated using (public.is_super_admin((select auth.uid()))) with check (public.is_super_admin((select auth.uid())));